import {Sound} from './sound.mjs';
import {FrontierUI,repeat,recipe} from './frontier-ui.mjs';
import {tickGlobe,startPlanetGame,planetComplete} from './globe.mjs';
const $=id=>document.getElementById(id),query=new URLSearchParams(location.search),qa=query.get('qa'),legacyQA=!!qa&&query.get('legacy')==='1';
const key=qa?'skyblock-frontier.qa.'+qa:'skyblock-frontier.v1';
let state;try{state=restore(localStorage.getItem(key));}catch{state=createState();}
if(!legacyQA)startPlanetGame(state);
const sound=new Sound();sound.mute(state.muted);
let art;try{art=new Art($('scene'),state);$('loading').hidden=true;}catch(err){$('loading').classList.add('error');$('loading').innerHTML='<strong>3D graphics could not start.</strong><p>Please enable WebGL or try a current browser.</p>';console.error(err);throw err;}
let paused=false,overview=false,resetConfirm=false,last=performance.now(),uiClock=0,saveClock=0,toastUntil=0,path=[],pointer=null,stick={x:0,y:0},pilot=null,qaStarted=0,qaStop=null,qaPack=false,qaGlobe=false;
const keys=new Set(),labels=new Map();
const homeArt=art,frontier=new FrontierUI(homeArt.renderer,{getState:()=>state,save,toast,sound,onShowWorld:showWorld,onTravel:()=>{paused=false;overview=false;path=[];pilot=null;qaGlobe=false;keys.clear();stick={x:0,y:0};pointer=null;document.body.classList.remove('overview','world-gallery');$('map').setAttribute('aria-label','Island overview');$('dialog').hidden=true;}});
function syncMode(){const next=frontier.active?frontier.art:homeArt;if(art!==next){art=next;art.resize();path=[];overview=false;document.body.classList.remove('overview','world-gallery');}document.body.classList.toggle('frontier-mode',frontier.active);document.body.classList.toggle('planet-main',frontier.active&&state.mode==='planet');document.body.classList.toggle('planet-blessed',frontier.active&&state.starCount>0);}
for(const site of SITES){const el=document.createElement('button');el.className='marker hidden';el.setAttribute('aria-label',`Walk to ${site.name}`);el.innerHTML=`<span class="marker-title">${site.name}</span><span class="cost"></span>`;el.addEventListener('pointerdown',e=>e.stopPropagation());el.addEventListener('click',()=>go(xy(site.at)));$('world-labels').append(el);labels.set(site.id,el);}
for(const a of SERVICES){const el=document.createElement('button');el.className='marker service hidden';el.setAttribute('aria-label',`Walk to ${a.name}`);el.innerHTML=`<span class="marker-title">${repeat}${a.name}</span><span class="cost recipe">${recipe(a)}</span>`;el.setAttribute('aria-label',`Walk to ${a.name}: ${a.hint}. Repeats while standing.`);el.addEventListener('pointerdown',e=>e.stopPropagation());el.addEventListener('click',()=>go(xy(a.at)));$('world-labels').append(el);labels.set(a.id,el);}
function save(){try{localStorage.setItem(key,JSON.stringify(state));$('save-label').textContent=qa?'QA save · isolated':'Autosaved';}catch{$('save-label').textContent='Save unavailable';}}
function go(target){if(frontier.active){frontier.go(target);return;}sound.start();overview=false;document.body.classList.remove('overview','world-gallery');path=findPath(state,target);if(!path.length)toast('Walk a little closer first.');}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');toastUntil=performance.now()+2400;}
function gain(resource,amount,point){const p=art.project(point.x,1.6,point.z),el=document.createElement('span');el.className='gain';el.style.left=`${p.x}px`;el.style.top=`${p.y}px`;el.innerHTML=`+${amount}${icon(resource)}`;$('pickups').append(el);setTimeout(()=>el.remove(),900);}
function onEvents(events){for(const e of events){if(e.globe){frontier.onEvents(e);if(!pilot)sound.event(e);continue;}art.handle(state,e);if(!pilot)sound.event(e);if(e.type==='harvest'){gain(e.resource,e.amount,xy(NODES.find(n=>n.id===e.node).at));const el=$('res-'+e.resource);if(el){el.classList.remove('bump');void el.offsetWidth;el.classList.add('bump');}}if(e.type==='build'){const a=SITES.find(p=>p.id===e.site);toast(e.site==='stone-tools'?'Stone tools! Double harvest + iron ore.':e.site==='iron-tools'?'Iron tools! Triple harvest + obsidian.':`${a.name} discovered!`);save();}if(e.type==='service')for(const [k,v]of Object.entries(e.reward))gain(k,v,state.player);if(e.type==='treasure'){toast('Treasure found! +6 Emeralds');gain('emerald',6,state.player);}if(e.type==='win'){save();setTimeout(((winningState)=>()=>{if(state===winningState&&state.won&&!frontier.active)openDialog(true);})(state),900);}}}
function updateUI(){frontier.updateUI();if(frontier.active)return;$('world-number').textContent='WORLD 1';const t=task(state);$('quest-title').textContent=t.title;$('quest-text').textContent=t.text;$('chapter').textContent=state.won?'YOUR WORLD · PORTAL RESTORED':state.done.includes('ruins')?'CHAPTER III · ANCIENT RUINS':state.done.includes('quarry')?'CHAPTER II · IRON & FIRE':'CHAPTER I · A SMALL BEGINNING';const visible=['wood','stone'];if(state.done.includes('quarry'))visible.push('ore','iron');if(state.done.includes('pasture'))visible.push('wheat');if(state.done.includes('pasture')||state.done.includes('ruins'))visible.push('emerald');if(state.done.includes('ruins'))visible.push('obsidian');for(const k of visible){let el=$('res-'+k);if(!el){el=document.createElement('div');el.id='res-'+k;el.className='resource';el.innerHTML='<span></span>'+icon(k);$('resources').append(el);}el.setAttribute('aria-label',`${RES[k].name}: ${state.bag[k]}`);el.querySelector('span').textContent=state.bag[k]>9999?(state.bag[k]/1000).toFixed(1)+'k':state.bag[k];}for(const el of [...$('resources').children])if(!visible.includes(el.id.slice(4)))el.remove();$('tool-label').textContent=`LVL ${state.tier}`;$('tool-icon').innerHTML=icon('axe')+icon('pick');$('avatar').innerHTML=icon('avatar');$('region').textContent=state.done.includes('ruins')?'ANCIENT RUINS':state.done.includes('quarry')?'IRON QUARRY':'GREENHAVEN';
 const sites=availableSites(state);for(const a of SITES){const el=labels.get(a.id);el.dataset.available=sites.includes(a)?'true':'false';el.classList.toggle('goal',t.site===a.id);if(!sites.includes(a))continue;const rem=remaining(state,a);el.querySelector('.cost').innerHTML=Object.entries(rem).filter(([,v])=>v>0).map(([k,v])=>`<span class="pair ${state.bag[k]>=v?'enough':''}"><b>${a.cost[k]-v}<small>/${a.cost[k]}</small></b>${icon(k)}</span>`).join('')||'✓';}
}
function labelsPosition() {
  if(frontier.active){for(const el of labels.values())el.classList.add('hidden');frontier.labelsPosition();return;}
  const hudBottom = 76;
  const entries = [];
  for (const a of [...SITES, ...SERVICES]) {
    const el = labels.get(a.id);
    const active = SERVICES.includes(a) ? state.done.includes(a.from) : el.dataset.available === 'true';
    const at = xy(a.at), p = art.project(at.x, .35, at.z);
    const shown = active && p.visible && p.y > hudBottom + 36 && p.y < art.h - 105 && p.x > 10 && p.x < art.w - 10;
    el.classList.toggle('hidden', !shown);
    if (shown) entries.push({el, p, w:el.offsetWidth, h:el.offsetHeight});
  }
  entries.sort((a,b) => a.p.y-b.p.y);
  const used=[];
  const hud=$('resources').getBoundingClientRect();
  const bounds=(e)=>({left:e.x-e.w/2,right:e.x+e.w/2,top:e.y-e.h,bottom:e.y});
  for (const entry of entries) {
    const {el,p,w,h}=entry;
    entry.x=Math.max(w/2+10,Math.min(art.w-w/2-10,p.x));
    entry.y=p.y;
    if(entry.x+w/2>hud.left-5&&entry.y>hud.top&&entry.y-h<hud.bottom)entry.x=Math.max(w/2+10,hud.left-w/2-9);
    for(let tries=0;tries<40;tries++) {
      const a=bounds(entry),other=used.find(r=>{const b=bounds(r);return a.right+5>b.left&&a.left-5<b.right&&a.bottom+5>b.top&&a.top-5<b.bottom;});
      if(!other)break;
      const b=bounds(other),overlap=Math.min(a.right,b.right)-Math.max(a.left,b.left);
      if(overlap<28){
        const right=entry.x>=other.x,need=overlap+7;
        const room=right?art.w-10-w/2-entry.x:entry.x-w/2-10;
        const take=Math.min(need,Math.max(0,room));
        const otherRoom=right?other.x-other.w/2-10:art.w-10-other.w/2-other.x;
        if(otherRoom>=need-take){entry.x+=(right?1:-1)*take;other.x+=(right?-1:1)*(need-take);continue;}
      }
      entry.y-=12;
    }
    if(entry.y-h<hudBottom){el.classList.add('hidden');continue;}
    used.push(entry);
  }
  for(const {el,p,x,y} of used){
    el.style.left=x+'px';el.style.top=y+'px';
    const dx=p.x-x,dy=Math.max(0,p.y-y-3);
    el.style.setProperty('--leader',Math.hypot(dx,dy)+'px');
    el.style.setProperty('--line-angle',Math.atan2(-dx,dy)+'rad');
  }
}

function context(near){if(frontier.active){frontier.context(near);return;}let kind='',title='',detail=path.length?'Walking… drag to take control.':state.totalGathered===0?'Drag to move. Stand near a tree.':'',progress=0;
 if(!near){const n=activeNodes(state).find(n=>state.nodes[n.id].left===0&&Math.hypot(state.player.x-xy(n.at).x,state.player.z-xy(n.at).z)<2);if(n){const seconds=Math.max(0,Math.ceil(state.nodes[n.id].ready-state.time));kind='RESOURCES REGROW';title=n.type==='wood'?'The oak will grow back.':'This deposit is recovering.';detail=seconds>0?`Ready in ${seconds}s. You can explore while it grows.`:'Step away to give it room to grow.';progress=1-Math.max(0,state.nodes[n.id].ready-state.time)/n.regen;}}
 if(near?.kind==='node'){const n=near.data,r=state.nodes[n.id];kind=state.tier<n.tier?'UPGRADE NEEDED':'AUTO HARVEST';title=state.tier<n.tier?`${n.tier===2?'Stone':'Iron'} tools required`:n.type==='wood'?'Chopping oak':n.type==='wheat'?'Harvesting wheat':`Mining ${RES[n.type].name.toLowerCase()}`;detail=state.tier<n.tier?'Craft them at your workbench.':`${r.left} hits left · regrows in ${n.regen}s`;progress=1-r.left/n.hits;}
 if(near?.kind==='site'){const a=near.data,rem=remaining(state,a),total=Object.values(a.cost).reduce((a,b)=>a+b,0);kind='STAND HERE TO BUILD';title=a.name;detail=Object.entries(rem).filter(([,v])=>v>0).map(([k,v])=>`${v} ${RES[k].name}`).join(' + ');progress=1-Object.values(rem).reduce((a,b)=>a+b,0)/total;if(!Object.entries(rem).some(([k,v])=>v>0&&state.bag[k]>0))kind='GATHER MORE MATERIALS';}
 if(near?.kind==='service'){const a=near.data;kind='↻ REPEATS WHILE STANDING';title=a.name;detail=a.hint;progress=state.serviceClock/a.time;}
 if(state.won&&!near){kind='PORTAL RESTORED';title='Your planet adventure starts here.';detail='Tap EXPAND PLANET to grow a complete globe.';}
 $('context').classList.toggle('active',!!near);$('context-kind').textContent=kind;$('context-title').textContent=title;$('context-detail').textContent=detail;$('context-progress').firstElementChild.style.width=Math.max(0,progress*100)+'%';
}
function openDialog(win=false){paused=true;pointer=null;stick={x:0,y:0};keys.clear();path=[];frontier.path=[];$('stick').style.transform='';$('dialog').hidden=false;$('dialog-title').textContent=win?'Your world is alive.':'Take a breath.';$('dialog-copy').textContent=win?'From a single tree to a glowing portal. You restored the ancient gateway — and the global frontier is unlocked! Expand a complete 642-tile planet, then travel to the next. Your backpack and tools carry over.':'Drag anywhere to move, or tap the ground to walk. Get close to resources to harvest automatically. Stand in a glowing pad to deliver materials. Tap the objective to find your way.';$('dialog-stats').innerHTML=win?`<span>${tilesFor(state.done,state.paid).length} land blocks</span><span>${state.totalGathered} gathered</span><span>${Math.floor(state.time/60)}m ${Math.floor(state.time%60)}s</span>`:'';$('frontier-travel').hidden=legacyQA?!state.won:!state.done.length;$('frontier-travel').textContent=frontier.active?'Visit original island':'Return to planet →';if(frontier.active){$('dialog-copy').textContent='Collect resources, then move to another deposit when one runs out. Trade at ↻ markers and tap border costs to build. Golden ★ key pieces ask for a few extra materials. Fill all 642 pieces to discover the planet’s secret. GOAL finds the next material; the map shows the whole globe.';$('dialog-stats').innerHTML=`<span>${state.frontier.owned.length} / 642 pieces</span><span>${state.starCount||0} ${(state.starCount||0)===1?'world':'worlds'} awakened</span>`;}$('sound').textContent=`Sound: ${state.muted?'off':'on'}`;resetConfirm=false;$('restart').textContent=legacyQA?'Start a new world':'Restart planet adventure';$('restart').classList.remove('confirm');$('cancel-reset').hidden=true;save();}
function resume(){paused=false;$('dialog').hidden=true;last=performance.now();sound.start();}
$('frontier-travel').onclick=()=>{frontier.active?frontier.leave():frontier.enter();syncMode();resume();};$('settings').onclick=()=>openDialog();$('resume').onclick=resume;$('sound').onclick=()=>{state.muted=!state.muted;sound.mute(state.muted);sound.start();$('sound').textContent=`Sound: ${state.muted?'off':'on'}`;save();};$('restart').onclick=()=>{if(!resetConfirm){resetConfirm=true;$('restart').textContent=legacyQA?'Confirm — start from the first tree':'Confirm — restart from the first pieces';$('restart').classList.add('confirm');$('cancel-reset').hidden=false;return;}const muted=state.muted;frontier.closeCelebration();state=legacyQA?createState():createPlanetState();state.muted=muted;frontier.path=[];syncMode();homeArt.updateWorld(state,true);path=[];pilot=null;overview=false;document.body.classList.remove('overview','world-gallery');save();updateUI();resume();toast(legacyQA?'A fresh little beginning.':'A fresh planet. A secret at 100%.');};$('cancel-reset').onclick=()=>openDialog(state.won);
function showWorld(value=true){overview=value;path=[];cancelInput();document.body.classList.toggle('overview',overview);document.body.classList.toggle('world-gallery',overview&&frontier.active&&planetComplete(state.frontier)&&state.frontier.rewardClaimed);$('map').setAttribute('aria-label',overview?'Return to explorer':'Island overview');sound.start();}
$('map').onclick=()=>showWorld(!overview);$('home').onclick=()=>frontier.active?frontier.home():go(state.done.includes('meadow')?xy([3,1]):xy([0,.5]));$('quest').onclick=()=>{if(frontier.active){frontier.goal();return;}if(state.won){frontier.enter();return;}const t=task(state);if(t.target)go(t.target);};
const canvas=$('scene');
function cancelInput(){if(frontier._art)frontier.art.galleryDragging=false;$('joystick').classList.remove('moving');pointer=null;stick={x:0,y:0};keys.clear();frontier.path=[];$('stick').style.transform='';}
canvas.addEventListener('pointerdown',e=>{if(paused||frontier.celebration)return;sound.start();canvas.setPointerCapture(e.pointerId);if(overview&&frontier.active&&planetComplete(state.frontier)&&state.frontier.rewardClaimed){pointer={id:e.pointerId,x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,dragged:false,gallery:true};frontier.art.galleryDragging=true;return;}pointer={id:e.pointerId,x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,dragged:false};path=[];overview=false;document.body.classList.remove('overview','world-gallery');$('joystick').classList.add('moving');$('joystick').style.left=(e.clientX-46)+'px';$('joystick').style.top=(e.clientY-46)+'px';});
canvas.addEventListener('pointermove',e=>{if(!pointer||e.pointerId!==pointer.id)return;if(pointer.gallery){frontier.art.rotateOverview(e.clientX-pointer.lastX,e.clientY-pointer.lastY);pointer.lastX=e.clientX;pointer.lastY=e.clientY;pointer.dragged=true;return;}pointer.lastX=e.clientX;pointer.lastY=e.clientY;const dx=e.clientX-pointer.x,dy=e.clientY-pointer.y,l=Math.hypot(dx,dy);if(l>6)pointer.dragged=true;const scale=Math.min(1,l/38);stick={x:l>0?dx/l*scale:0,y:l>0?dy/l*scale:0};$('stick').style.transform=`translate(${stick.x*25}px,${stick.y*25}px)`;});
canvas.addEventListener('pointerup',e=>{if(!pointer||pointer.id!==e.pointerId)return;if(pointer.gallery){cancelInput();return;}const wasTap=!pointer.dragged,p={x:e.clientX,y:e.clientY};cancelInput();if(wasTap){const rect=canvas.getBoundingClientRect(),target=art.groundPoint(p.x-rect.left,p.y-rect.top);if(target)go(target);}});
canvas.addEventListener('pointercancel',cancelInput);window.addEventListener('blur',()=>{cancelInput();path=[];save();});document.addEventListener('visibilitychange',()=>{cancelInput();path=[];save();last=performance.now();});
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d','W','A','S','D'].includes(e.key)){e.preventDefault();keys.add(e.key.toLowerCase());path=[];sound.start();}if(e.key==='Escape')paused?resume():openDialog();});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('resize',()=>art.resize());window.addEventListener('pagehide',save);
// A second preview must adopt the latest save instead of overwriting a newer planet.
window.addEventListener('storage',e=>{if(e.key!==key||!e.newValue)return;state=restore(e.newValue);if(!legacyQA&&state.mode!=='planet')startPlanetGame(state);cancelInput();path=[];pilot=null;saveClock=0;sound.mute(state.muted);syncMode();art.updateWorld(state,true);updateUI();});
function input(dt){if(pilot)return pilot.input(state,dt);let x=stick.x,y=stick.y;x+=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0);y+=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);if(frontier.active){const len=Math.max(1,Math.hypot(x,y));return frontier.input(dt,x/len,y/len);}if(x||y){path=[];const len=Math.hypot(x,y);x/=Math.max(1,len);y/=Math.max(1,len);return {...art.movement(x,y)};}while(path.length&&Math.hypot(path[0].x-state.player.x,path[0].z-state.player.z)<.14)path.shift();if(path.length&&!canStand(state,path[0].x,path[0].z))path=findPath(state,path.at(-1));if(path.length){const target=path[0],dx=target.x-state.player.x,dz=target.z-state.player.z,len=Math.hypot(dx,dz);return {x:dx/len*Math.min(1,len/(3.7*dt)),z:dz/len*Math.min(1,len/(3.7*dt))};}return {x:0,z:0};}
if(qa){const panel=document.createElement('div');panel.id='qa-panel';panel.innerHTML='<button id="qa-run">Run legal campaign</button><select id="qa-stage" aria-label="QA checkpoint"><option value="meadow">First expansion</option><option value="stone-tools">Stone tools</option><option value="quarry">Quarry</option><option value="ruins">Ruins</option></select><button id="qa-spine">Run checkpoint</button><button id="qa-pack">Gather wood (24)</button><button id="qa-globe">Run planet checkpoint (30 tiles)</button><button id="qa-full-globe">Run full planet (642 tiles)</button><button id="qa-hide">Hide QA</button><span id="qa-status">Isolated QA save. No grants / teleports.</span>';$('game').append(panel);$('qa-hide').onclick=()=>panel.hidden=true;if(!legacyQA)for(const id of['qa-run','qa-stage','qa-spine','qa-pack'])$(id).hidden=true;$('qa-globe').onclick=()=>runGlobeQA(30);$('qa-full-globe').onclick=()=>runGlobeQA(642);$('qa-pack').onclick=async()=>{qaGlobe=false;const {LegalPilot}=await import('./autoplay.mjs');pilot=new LegalPilot();pilot.choose=s=>pilot.resource(s,'wood',24);qaPack=true;qaStop=null;qaStarted=state.time;paused=false;};$('qa-spine').onclick=async()=>{qaGlobe=false;qaPack=false;const {LegalPilot}=await import('./autoplay.mjs');pilot=new LegalPilot();qaStop=$('qa-stage').value;qaStarted=state.time;paused=false;};$('qa-run').onclick=async()=>{qaGlobe=false;qaStop=null;qaPack=false;const {LegalPilot}=await import('./autoplay.mjs');pilot=new LegalPilot();qaStarted=state.time;paused=false;$('dialog').hidden=true;$('qa-run').disabled=true;};}
async function runGlobeQA(limit){if(!state.won&&state.mode!=='planet'){$('qa-status').textContent='Restore the portal first using Run legal campaign.';return;}const {GlobePilot}=await import('./frontier-pilot.mjs');if(!frontier.active)frontier.enter();syncMode();qaGlobe=true;qaPack=false;qaStop=null;pilot=new GlobePilot({limit});qaStarted=state.time;paused=false;overview=false;$('dialog').hidden=true;}
function frame(now){requestAnimationFrame(frame);syncMode();const raw=Math.min(.05,Math.max(.001,(now-last)/1000));last=now;let result={moved:false,near:null,events:[]};if(!paused&&!overview&&!frontier.celebration&&!document.hidden){const steps=pilot?200:1,dt=pilot?.05:raw;for(let i=0;i<steps;i++){const r=frontier.active?tickGlobe(state,dt,input(dt)):tick(state,dt,input(dt));result.moved ||=r.moved;result.near=r.near;onEvents(r.events);if(pilot&&qaGlobe&&(pilot.finished||pilot.failed||state.time-qaStarted>18000)){$('qa-status').textContent=pilot.finished?`PASS · ${state.frontier.owned.length}/642 tiles · planet ${state.frontier.index}\n${Math.round(state.time-qaStarted)} simulated seconds · real gathering / recipes`:pilot.failed||`TIMEOUT at ${pilot.status}`;pilot=null;paused=true;save();break;}if(pilot&&!qaGlobe&&((qaPack&&state.bag.wood>=24)||state.won||(qaStop&&state.done.includes(qaStop))||pilot.failed||state.time-qaStarted>1800)){const text=qaPack&&state.bag.wood>=24?'Pack gathered legally · 24 Wood':qaStop&&state.done.includes(qaStop)?`Checkpoint complete · ${qaStop}`:state.won?`PASS · portal restored\n${Math.round(state.time)} simulated seconds\n${state.done.length} sites · ${state.totalGathered} gathered · ${state.totalTrades} recipes`:pilot.failed||`TIMEOUT at ${pilot.status}`;$('qa-status').textContent=text;$('qa-run').disabled=false;if((qaPack&&state.bag.wood>=24)||(qaStop&&state.done.includes(qaStop)))paused=true;pilot=null;save();break;}}sound.update(raw);saveClock+=raw;if(saveClock>3){saveClock=0;save();}}frontier.frame(raw);art.render(state,raw,{celebration:frontier.celebration,moved:result.moved,overview,near:result.near,path});labelsPosition();context(result.near);uiClock+=raw;if(uiClock>.13){uiClock=0;updateUI();if(pilot)$('qa-status').textContent=`Legal route: ${pilot.status}\n${Math.round(state.time)}s · ${state.done.length} sites`;}if(toastUntil&&now>toastUntil){toastUntil=0;$('toast').classList.remove('show');}}
syncMode();updateUI();save();if(query.get('view')==='world'&&planetComplete(state.frontier)&&state.frontier.rewardClaimed){showWorld(true);if(qa)$('qa-panel').hidden=true;}if(!legacyQA&&state.frontier.owned.length===19&&state.totalGathered===0)toast('Collect → trade → build. A secret waits at 100%.');requestAnimationFrame(frame);

// QA driver. Uses only the same movement and tick APIs as the player. Never grants
// inventory, unlocks land, teleports, skips waits or overwrites campaign state.
