import test from 'node:test';
import assert from 'node:assert/strict';
import {createState,restore,tick,move,canStand,onGround,remaining,availableSites,tilesFor,findPath,xy,RES,SITES,NODES,SERVICES,task,TREASURE_AT} from '../core.mjs';
import {LegalPilot} from '../autoplay.mjs';
const steps=(s,seconds,input={x:0,z:0})=>{let events=[];for(let i=0;i<Math.ceil(seconds/.05);i++)events.push(...tick(s,.05,input).events);return events;};
test('new world has one tree, nine land tiles and an intelligible first goal',()=>{const s=createState();assert.equal(tilesFor(s.done).length,9);assert.equal(availableSites(s).length,1);assert.equal(task(s).title,'Gather wood');assert.deepEqual(s.bag,{wood:0,stone:0,ore:0,iron:0,wheat:0,emerald:0,obsidian:0});});
test('walking cannot cross an island edge, including diagonal input',()=>{for(const [x,z]of [[1,0],[-1,0],[0,1],[0,-1],[1,1],[-1,-1]]){const s=createState();for(let i=0;i<300;i++)move(s,x,z,.05);assert.ok(onGround(s,s.player.x,s.player.z));assert.ok(canStand(s,s.player.x,s.player.z));}});
test('tree auto-harvest yields real inventory and exhausts the tree',()=>{const s=createState();s.player={...xy([-.7,.1]),angle:0};const events=steps(s,4);assert.equal(s.bag.wood,8);assert.ok(events.some(e=>e.type==='deplete'));assert.equal(s.totalGathered,8);});
test('resources regenerate, but solid trees never regrow around the player',()=>{const s=createState(),n=NODES[0];s.nodes[n.id]={left:0,ready:0};s.player={...xy(n.at),angle:0};steps(s,1);assert.equal(s.nodes[n.id].left,0);s.player={x:2,z:2,angle:0};steps(s,.1);assert.equal(s.nodes[n.id].left,n.hits);});
test('construction only spends owned materials, keeps partial progress and builds once',()=>{const s=createState(),site=SITES[0];s.player={...xy(site.at),angle:0};s.bag.wood=3;steps(s,2);assert.equal(s.bag.wood,0);assert.equal(remaining(s,site).wood,5);assert.equal(s.done.length,0);const resumed=restore(JSON.stringify(s));assert.equal(remaining(resumed,site).wood,5);resumed.bag.wood=5;const events=steps(resumed,2);assert.deepEqual(resumed.done,['meadow']);assert.equal(events.filter(e=>e.type==='build').length,1);assert.equal(resumed.totalSpent,8);steps(resumed,1);assert.equal(resumed.done.length,1);});
test('partial investment opens real connected hexes before the whole region is paid',()=>{const s=createState(),site=SITES[0];s.player={...xy(site.at),angle:0};s.bag.wood=3;steps(s,2);const ground=tilesFor(s.done,s.paid);assert.equal(ground.length,12);assert.equal(s.done.includes('meadow'),false);for(const t of ground){const p=xy(t.at);assert.ok(onGround(s,p.x,p.z,.01));}const r=restore(JSON.stringify(s));assert.equal(tilesFor(r.done,r.paid).length,12);});
test('legacy square-grid save migrates the player onto the new hex grid',()=>{const legacy=createState();legacy.version=1;legacy.done=['meadow'];legacy.player={x:4.4,z:0,angle:0};legacy.bag.wood=17;const r=restore(legacy);assert.equal(r.version,4);assert.equal(r.bag.wood,17);assert.ok(onGround(r,r.player.x,r.player.z));});
test('iron ore is gated by stone tools, and tiers increase actual yield',()=>{const s=createState(),n=NODES.find(n=>n.type==='ore');s.done=['meadow','bridge','quarry'];s.player={x:xy(n.at).x-1.1,z:xy(n.at).z,angle:0};steps(s,1);assert.equal(s.bag.ore,0);s.tier=2;steps(s,.5);assert.equal(s.bag.ore,2);s.tier=3;steps(s,.5);assert.equal(s.bag.ore,5);});
