const completed=()=>{const s=createState();s.done=SITES.map(s=>s.id);s.won=true;s.tier=3;enterFrontier(s);return s;};
const wait=(s,seconds)=>{const events=[];for(let i=0;i<Math.ceil(seconds/.05);i++)events.push(...tickGlobe(s,.05).events);return events;};
test('642 geodesic cells form one closed globe, with twelve pentagons and reciprocal edges',()=>{const p=planet(1);assert.equal(p.cells.length,642);assert.equal(p.cells.filter(c=>c.neighbors.length===5).length,12);for(const c of p.cells){assert.ok(Math.abs(Math.hypot(...c.p)-1)<1e-10);assert.equal(c.corners.length,c.neighbors.length);assert.ok(c.neighbors.every(n=>p.cells[n].neighbors.includes(c.id)));assert.equal(cellAt(p,c.p),c.id);}const seen=new Set([p.start]),q=[p.start];for(let i=0;i<q.length;i++)for(const id of p.cells[q[i]].neighbors)if(!seen.has(id)){seen.add(id);q.push(id);}assert.equal(seen.size,642);assert.ok(p.cells.some(c=>dot(c.p,p.cells[p.start].p)<-.99));});
test('each generated planet starts with all renewable inputs and three repeatable exchanges',()=>{for(const index of[1,2,9,91]){const p=planet(index),types=new Set(p.initial.map(id=>p.cells[id].type));for(const type of['wood','stone','ore','wheat','obsidian'])assert.ok(types.has(type));assert.equal(p.services.length,3);assert.equal(p.initial.length,19);assert.notDeepEqual(p.cells.map(c=>c.biome),planet(index+1).cells.map(c=>c.biome));}});
