test('land uses exact owned inputs, partial investment survives reload, new nodes cannot trap builder',()=>{const s=completed(),g=s.frontier,p=planet(g.index),c=boundaries(g).find(c=>Object.keys(c.cost).length===2);selectLand(g,c.id);g.pos=[...buildAnchor(g,c.id)];s.bag.wood=2;wait(s,.8);assert.equal(s.bag.wood,0);assert.equal(g.paid[c.id].wood,2);assert.equal(g.owned.includes(c.id),false);const r=restore(JSON.stringify(s)),rem=globeRemaining(r.frontier,c);for(const[k,v]of Object.entries(rem))r.bag[k]=v;const e=wait(r,5);assert.ok(r.frontier.owned.includes(c.id));assert.equal(e.filter(e=>e.type==='build').length,1);assert.ok(globeCanStand(r.frontier,r.frontier.pos));assert.equal(r.frontier.selected,null);});
