  const cooling=restore(JSON.stringify(s));assert.equal(nodeState(cooling.frontier,c.id).waitDeparture,false);assert.equal(nodeState(cooling.frontier,c.id).ready,nodeState(g,c.id).ready);
  assert.ok(wait(s,5.2).some(e=>e.type==='regrow'&&e.cell===c.id));g.pos=[...c.p];assert.ok(wait(s,.5).some(e=>e.type==='harvest'&&e.cell===c.id));
 }
